      showFeedback(`Focus started for ${session.taskTitle}.`);
    }
  } catch (error) {
    showFeedback(String(error.message || error));
  }
});
elements.focusPause.addEventListener('click', () => pauseActiveFocus());
elements.focusResume.addEventListener('click', () => {
