const MAX_DURATION_MINUTES = 480;
const ACTIVE_STATUSES = new Set(['running', 'paused']);
const HISTORY_OUTCOMES = new Set(['completed', 'finishedEarly', 'cancelled']);

function isTimestamp(value) {
